Description: This Terraform configuration creates an AWS public NAT Gateway in a specified subnet using a specified Elastic IP allocation ID. The subnet ID and Elastic IP allocation ID are configurable variables with default placeholder values that should be replaced with real AWS resource IDs before deployment.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the NAT Gateway will be created."
  type        = string
  default     = "us-east-1"
}

variable "subnet_id" {
  description = "The ID of the public subnet where the NAT Gateway will be created."
  type        = string
  default     = "subnet-0123456789abcdef0"
}

variable "elastic_ip_allocation_id" {
  description = "The allocation ID of the Elastic IP address to associate with the NAT Gateway."
  type        = string
  default     = "eipalloc-0123456789abcdef0"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway."
  type        = string
  default     = "public-nat-gateway"
